package com.zineb.chat.server.view;
import javafx.collections.*; import javafx.geometry.Insets; import javafx.scene.Parent; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.scene.paint.Color; import javafx.scene.shape.Circle; import java.util.*;
public final class ServerView {
    private final GridPane root=new GridPane(); private final Label status=new Label("Offline"); private final Circle light=new Circle(6,Color.CRIMSON); private final TextArea log=new TextArea(); private final ListView<String> users=new ListView<>(); private final Map<String,String> colors=new HashMap<>();
    public ServerView(){ root.setPadding(new Insets(18)); root.setHgap(14); root.setVgap(10); ColumnConstraints a=new ColumnConstraints();a.setPercentWidth(70);ColumnConstraints b=new ColumnConstraints();b.setPercentWidth(30);root.getColumnConstraints().addAll(a,b); Label title=new Label("Zineb's TCP Chat Server");title.getStyleClass().add("title"); log.setEditable(false); log.setWrapText(true); users.setCellFactory(v->new ListCell<>(){protected void updateItem(String s,boolean empty){super.updateItem(s,empty);if(empty||s==null){setText(null);setStyle("");}else{setText(s);setStyle("-fx-background-color:"+colors.computeIfAbsent(s,k->randomPastel())+";-fx-background-radius:8;-fx-padding:7;");}}}); root.add(title,0,0);root.add(new HBox(8,new Label("Status:"),status,light),0,1);root.add(new Label("Activity Log"),0,2);root.add(log,0,3);root.add(new Label("Connected Users"),1,2);root.add(users,1,3);GridPane.setVgrow(log,Priority.ALWAYS);GridPane.setVgrow(users,Priority.ALWAYS); }
    private String randomPastel(){Random r=new Random();return String.format("#%02x%02x%02x",180+r.nextInt(60),180+r.nextInt(60),180+r.nextInt(60));}
    public Parent root(){return root;} public void addLog(String s){log.appendText(s+System.lineSeparator());} public void setUsers(List<String> u){users.setItems(FXCollections.observableArrayList(u));colors.keySet().retainAll(u);} public void setStatus(boolean online,String host,int port){status.setText(online?"Online - "+host+":"+port:"Offline");light.setFill(online?Color.LIMEGREEN:Color.CRIMSON);}
}
